/* Génération locale des PDF : jsPDF et AutoTable sont copiés dans vendor/.
 * Ce module ne télécharge rien et ne sauvegarde rien : l'application conserve
 * le Blob retourné dans IndexedDB et, éventuellement, dans le dossier choisi.
 */
(() => {
  'use strict';

  // Copie exacte du PNG, utilisée seulement si le fichier ou le canvas est refusé
  // (notamment en file://). Si le logo est remplacé, régénérer cette constante
  // en base64 avec les mêmes octets que logo-horizontal.png.
  const EMBEDDED_LOGO = 'data:image/png;base64,';

  const PAGE = { width: 210, height: 297, margin: 12, top: 24, bottom: 22 };
  let logoPromise;

  function controlType(record) {
    return record.type === 'bureaux' ? 'bureaux' : 'conciergerie';
  }

  function filename(record) {
    const date = /^\d{4}-\d{2}-\d{2}$/.test(record.date) ? record.date : new Date().toISOString().slice(0, 10);
    const building = String(record.buildingName || record.address || 'Controle')
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-zA-Z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 120) || 'Controle';
    return `${date}_${controlType(record)}_${building}.pdf`;
  }

  // Les caractères français et les tirets sont pris en charge par WinAnsi.
  // Les pictogrammes et caractères de contrôle n'ont pas de glyphe dans Helvetica.
  function text(value) {
    return String(value ?? '').replace(/\r\n?/g, '\n')
      .replace(/[\u00a0\u202f]/g, ' ').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
      .replace(/[\u200b-\u200f\u2060\ufeff]/g, '').replace(/[\u{1f000}-\u{1ffff}]/gu, '');
  }

  function palette() {
    const css = getComputedStyle(document.documentElement);
    const color = name => {
      const raw = css.getPropertyValue(`--${name}`).trim();
      if (!/^#[\da-f]{6}$/i.test(raw)) throw new Error(`Couleur PDF manquante : --${name}.`);
      return [1, 3, 5].map(start => parseInt(raw.slice(start, start + 2), 16));
    };
    return Object.fromEntries(['anthracite', 'gris', 'gris-clair', 'bleu', 'bleu-clair', 'alerte', 'blanc'].map(name => [name, color(name)]));
  }

  function loadImage(source) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error('Une image du contrôle ne peut pas être chargée.'));
      image.src = source;
    });
  }

  function loadLogo() {
    if (!logoPromise) {
      logoPromise = loadImage('logo-horizontal.png').then(image => {
        const canvas = document.createElement('canvas');
        canvas.width = image.naturalWidth;
        canvas.height = image.naturalHeight;
        canvas.getContext('2d').drawImage(image, 0, 0);
        return { data: canvas.toDataURL('image/png'), width: canvas.width, height: canvas.height };
      }).catch(() => loadImage(EMBEDDED_LOGO).then(image => ({
        data: EMBEDDED_LOGO, width: image.naturalWidth, height: image.naturalHeight
      }))).catch(error => { logoPromise = null; throw error; });
    }
    return logoPromise;
  }

  async function preparePhotos(photos = []) {
    // Décodage séquentiel pour limiter la mémoire sur téléphone. L'image reste
    // proportionnelle et ne dépasse pas la résolution des photos de l'application.
    const prepared = [];
    for (const photo of photos) {
      const image = await loadImage(photo.dataUrl);
      const scale = Math.min(1, 1280 / Math.max(image.naturalWidth, image.naturalHeight));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      const context = canvas.getContext('2d');
      context.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--blanc').trim();
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      prepared.push({ data: canvas.toDataURL('image/jpeg', .8), width: canvas.width, height: canvas.height, name: text(photo.name) });
      canvas.width = canvas.height = 1;
    }
    return prepared;
  }

  function photoRows(photos, label) {
    const rows = [];
    for (let index = 0; index < photos.length; index += 3) {
      rows.push({
        element: { content: '', colSpan: 6, styles: { minCellHeight: 47 } },
        _kind: 'photos', _photos: photos.slice(index, index + 3), _label: label, _offset: index
      });
    }
    return rows;
  }

  function drawPhotos(doc, hook, colors) {
    if (hook.section !== 'body' || hook.column.index !== 0 || hook.row.raw._kind !== 'photos') return;
    const { cell, row } = hook;
    const slotWidth = (cell.width - 8) / 3;
    row.raw._photos.forEach((photo, index) => {
      const scale = Math.min((slotWidth - 3) / photo.width, 34 / photo.height);
      const width = photo.width * scale;
      const height = photo.height * scale;
      const left = cell.x + 3 + index * slotWidth;
      const top = cell.y + 2;
      doc.addImage(photo.data, 'JPEG', left, top, width, height, undefined, 'FAST');
      doc.setFont('helvetica', 'normal').setFontSize(7).setTextColor(...colors.gris);
      const caption = `${row.raw._label} · Photo ${row.raw._offset + index + 1}`;
      const lines = doc.splitTextToSize(caption, slotWidth - 3).slice(0, 2);
      doc.text(lines, left, top + 37);
    });
  }

  async function generate(record, config) {
    if (!window.jspdf?.jsPDF || !window.jspdf.jsPDF.API.autoTable) {
      throw new Error('La bibliothèque PDF locale est indisponible. Rechargez l’application.');
    }
    const colors = palette();
    const logo = await loadLogo();
    const doc = new window.jspdf.jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4', compress: true });
    const type = controlType(record);
    const title = type === 'bureaux' ? 'Contrôle entretien de bureaux' : 'Modèle de contrôle des conciergeries';
    const width = PAGE.width - PAGE.margin * 2;
    const limit = PAGE.height - PAGE.bottom;
    const sections = config.sections || [];
    let y = 12;

    doc.setProperties({ title: `${title} – ${record.buildingName || record.address || ''}`, author: 'E. Blanco SA', subject: 'Contrôle sur place' });
    const logoHeight = 11;
    const logoWidth = logoHeight * logo.width / logo.height;
    doc.addImage(logo.data, 'PNG', (PAGE.width - logoWidth) / 2, y, logoWidth, logoHeight);
    y += 19;
    doc.setFont('helvetica', 'bold').setFontSize(15).setTextColor(...colors.anthracite);
    const titleLines = doc.splitTextToSize(title, width);
    doc.text(titleLines, PAGE.width / 2, y, { align: 'center' });
    y += titleLines.length * 6 + 5;

    function nextPage() {
      doc.addPage();
      y = PAGE.top;
    }

    function metadata(label, value) {
      doc.setFont('helvetica', 'normal').setFontSize(10);
      const lines = doc.splitTextToSize(text(value || '—'), width - 32);
      const height = Math.max(5, lines.length * 4.5);
      if (y + height > limit) nextPage();
      doc.setFont('helvetica', 'bold').setTextColor(...colors.anthracite).text(label, PAGE.margin, y);
      doc.setFont('helvetica', 'normal').text(lines, PAGE.margin + 32, y);
      y += height + 2;
    }

    if (record.buildingName) metadata('Immeuble', record.buildingName);
    metadata('Adresse', record.address);
    metadata(type === 'bureaux' ? 'Responsable' : 'Concierge', record.concierge);
    const parts = String(record.date || '').split('-');
    metadata('Date', parts.length === 3 ? `${parts[2]}.${parts[1]}.${parts[0]}` : record.date);
    y += 2;
    doc.setFontSize(8).setTextColor(...colors.gris);
    const legend = (config.ratings || []).map(rating => `${rating.value} = ${rating.label}`).join(' · ');
    if (legend) {
      const lines = doc.splitTextToSize(text(legend), width);
      if (y + lines.length * 4 + 8 > limit) nextPage();
      doc.text(lines, PAGE.margin, y);
      y += lines.length * 4 + 2;
    }
    const guidance = 'Joindre une photo pour la note 4 et pour tous les dégâts et actes de vandalisme.';
    doc.setTextColor(...colors.alerte).setFontSize(8).text(guidance, PAGE.margin, y);
    y += 6;

    function heading(value) {
      // Garde un titre avec le début de son tableau, sans toucher au pied de page.
      if (y + 37 > limit) nextPage();
      doc.setFillColor(...colors['bleu-clair']).setDrawColor(...colors.anthracite).setLineWidth(.25);
      doc.rect(PAGE.margin, y, width, 9, 'FD');
      doc.setFont('helvetica', 'bold').setFontSize(11).setTextColor(...colors.anthracite);
      doc.text(text(value), PAGE.margin + 3, y + 6);
      y += 11;
    }

    function table(body, comments = false) {
      doc.autoTable({
        startY: y,
        margin: { left: PAGE.margin, right: PAGE.margin, top: PAGE.top, bottom: PAGE.bottom },
        theme: 'grid', tableWidth: width,
        rowPageBreak: 'avoid', showHead: comments ? 'never' : 'everyPage',
        columns: [
          { header: 'Élément', dataKey: 'element' },
          ...[1, 2, 3, 4].map(value => ({ header: String(value), dataKey: `rating${value}` })),
          { header: 'Remarques', dataKey: 'remark' }
        ], body,
        styles: { font: 'helvetica', fontSize: 9, cellPadding: 2, minCellHeight: 8, lineColor: colors.anthracite, lineWidth: .15, textColor: colors.anthracite, fillColor: colors.blanc, overflow: 'linebreak', valign: 'top' },
        headStyles: { fillColor: colors['gris-clair'], textColor: colors.anthracite, fontStyle: 'bold' },
        columnStyles: {
          element: { cellWidth: 64, fontStyle: 'bold' },
          rating1: { cellWidth: 10, halign: 'center', valign: 'middle' },
          rating2: { cellWidth: 10, halign: 'center', valign: 'middle' },
          rating3: { cellWidth: 10, halign: 'center', valign: 'middle' },
          rating4: { cellWidth: 10, halign: 'center', valign: 'middle' },
          remark: { cellWidth: width - 104 }
        },
        didParseCell(hook) {
          if (hook.section !== 'body') return;
          if (hook.row.raw._kind === 'group') {
            hook.cell.styles.fillColor = colors['gris-clair'];
            hook.cell.styles.fontStyle = 'bold';
          }
          if (hook.row.raw._kind === 'comments') hook.cell.styles.fontStyle = 'normal';
          if (String(hook.column.dataKey).startsWith('rating') && hook.cell.text[0] === 'X') {
            hook.cell.styles.textColor = hook.column.dataKey === 'rating4' ? colors.alerte : colors.bleu;
            hook.cell.styles.fontStyle = 'bold';
          }
        },
        didDrawCell: hook => drawPhotos(doc, hook, colors)
      });
      y = doc.lastAutoTable.finalY + 5;
    }

    for (let sectionIndex = 0; sectionIndex < sections.length; sectionIndex++) {
      const section = sections[sectionIndex];
      const body = [];
      for (const group of section.groups || []) {
        if (group.title) body.push({ element: { content: text(group.title), colSpan: 6 }, _kind: 'group' });
        for (const item of group.items || []) {
          const row = record.rows?.[item.id] || {};
          body.push({ element: text(item.label), ...Object.fromEntries([1, 2, 3, 4].map(value => [`rating${value}`, Number(row.rating) === value ? 'X' : ''])), remark: text(row.remark) });
          if (row.photos?.length) body.push(...photoRows(await preparePhotos(row.photos), text(item.label)));
        }
      }
      heading(`${sectionIndex + 1}. ${section.title}`);
      table(body);
    }

    if (type === 'bureaux' && sections.length === 0) {
      heading('Modèle à venir');
      doc.setFont('helvetica', 'normal').setFontSize(10).setTextColor(...colors.gris);
      doc.text('Le modèle de contrôle des bureaux reste à compléter.', PAGE.margin, y + 3);
      y += 13;
    }
    heading(`${sections.length + 1}. COMMENTAIRES - REMARQUES`);
    const comments = record.comments || {};
    const commentRows = [{ element: { content: text(comments.text || '—'), colSpan: 6, styles: { minCellHeight: 14 } }, _kind: 'comments' }];
    commentRows.push(...photoRows(await preparePhotos(comments.photos), 'Commentaires'));
    table(commentRows, true);

    // Pied de page ajouté après pagination : il reste identique sur chaque page.
    const pages = doc.getNumberOfPages();
    for (let page = 1; page <= pages; page++) {
      doc.setPage(page);
      if (page > 1) {
        const smallHeight = 5;
        doc.addImage(logo.data, 'PNG', PAGE.margin, 10, smallHeight * logo.width / logo.height, smallHeight);
        doc.setFont('helvetica', 'normal').setFontSize(8).setTextColor(...colors.gris);
        const label = text(record.buildingName || record.address || title).replace(/\s+/g, ' ');
        const firstLine = doc.splitTextToSize(label, 120)[0] || '';
        doc.text(firstLine.length < label.length ? `${firstLine}…` : firstLine, PAGE.width - PAGE.margin, 14, { align: 'right' });
      }
      doc.setDrawColor(...colors.anthracite).setLineWidth(.2);
      doc.line(PAGE.margin, 278, PAGE.width - PAGE.margin, 278);
      doc.setFont('helvetica', 'normal').setFontSize(7).setTextColor(...colors.gris);
      const footer = doc.splitTextToSize(text(config.footer), width);
      doc.text(footer.slice(0, 3), PAGE.width / 2, 282, { align: 'center', lineHeightFactor: 1.2 });
      doc.text(`${page} / ${pages}`, PAGE.width / 2, 294, { align: 'center' });
    }
    return doc.output('blob');
  }

  window.CONTROL_PDF = Object.freeze({ generate, filename });
})();
